1	//! End-to-end regression tests for the validity-period (Not Before /
2	//! Not After) decoding and display behavior documented in README.md.
3	//!
4	//! Like `tests/name_display.rs`, these drive the real `chainview` binary so
5	//! the public contract is locked as a whole: on success the five fields keep
6	//! their fixed order, and malformed input means exit code 2, empty stdout and
7	//! the `chainview: invalid DER certificate:` stderr prefix with a non-empty
8	//! reason. Only time decoding is exercised here — signature verification,
9	//! trust and whether the certificate is currently expired are intentionally
10	//! out of scope: `inspect` displays fields, it never judges them.
11	//!
12	//! Coverage:
13	//! - `YYYY-MM-DDTHH:MM:SSZ` rendering for both UTCTime and GeneralizedTime;
14	//! - the UTCTime two-digit year pivot (<50 => 2000..2049, >=50 =>
15	//!   1950..1999), including the 49/50 boundary, and GeneralizedTime's
16	//!   four-digit years at and after 2050;
17	//! - the two time fields interpreting their own (possibly different)
18	//!   encodings independently;
19	//! - output independence from the local timezone;
20	//! - calendar validity (Gregorian leap years, range checks, no rollover)
21	//!   kept separate from expiry/not-yet-valid;
22	//! - strict textual form: mandatory seconds, trailing `Z`, no offsets,
23	//!   fractions, stray characters or other (non-time) tags, in either field.
24	//!
25	//! Certificates are built with the tiny zero-dependency DER constructor
26	//! copied below so individual time encodings can be crafted byte for byte.
27	
28	use std::fs;
29	use std::path::PathBuf;
30	use std::process::{Command, Output};
31	use std::sync::atomic::{AtomicU64, Ordering};
32	
33	const FIXED_SERIAL: &str = "0E8A4C2F9B17D603";
34	const FIXED_SUBJECT: &str = "CN=example.com";
35	const FIXED_ISSUER: &str = "CN=Test CA";
36	
37	// ----- Known X.520 attribute OID arcs -------------------------------------
38	
39	const CN: &[u64] = &[2, 5, 4, 3];
40	
41	const TAG_UTC_TIME: u8 = 0x17;
42	const TAG_GENERALIZED_TIME: u8 = 0x18;
43	
44	// ----- Success: year pivot and encodings -----------------------------------
45	
46	#[test]
47	fn utctime_year_pivot_49_is_2049_and_50_is_1950() {
48	    // The boundary years must map by the fixed rule, never to an adjacent
49	    // year: 49 is 2049 (not 1949), 50 is 1950 (not 2050). A certificate may
50	    // have Not After before Not Before; validity windows are not judged.
51	    let cert = default_cert(
52	        &utc(b"490630120000Z"),
53	        &utc(b"500101000000Z"),
54	    );
55	    let (out, _cert) = run_inspect("utc-pivot-49-50", &cert);
56	    assert_times_success(&out, "2049-06-30T12:00:00Z", "1950-01-01T00:00:00Z");
57	
58	    // The other end of each half: 00 is 2000 and 99 is 1999.
59	    let cert = default_cert(
60	        &utc(b"000101000000Z"),
61	        &utc(b"991231235959Z"),
62	    );
63	    let (out, _cert) = run_inspect("utc-pivot-00-99", &cert);
64	    assert_times_success(&out, "2000-01-01T00:00:00Z", "1999-12-31T23:59:59Z");
65	}
66	
67	#[test]
68	fn generalized_time_keeps_four_digit_years_including_2050_and_beyond() {
69	    // GeneralizedTime is read literally as a four-digit year — there is no
70	    // pivot — so 2050 and later render correctly, and a fully written 1949
71	    // is not moved into 2049.
72	    let cert = default_cert(
73	        &generalized(b"20500101000000Z"),
74	        &generalized(b"20991231235959Z"),
75	    );
76	    let (out, _cert) = run_inspect("gt-2050-2099", &cert);
77	    assert_times_success(&out, "2050-01-01T00:00:00Z", "2099-12-31T23:59:59Z");
78	
79	    let cert = default_cert(
80	        &generalized(b"19491231235959Z"),
81	        &generalized(b"20491231235959Z"),
82	    );
83	    let (out, _cert) = run_inspect("gt-1949-2049", &cert);
84	    assert_times_success(&out, "1949-12-31T23:59:59Z", "2049-12-31T23:59:59Z");
85	}
86	
87	#[test]
88	fn not_before_and_not_after_may_use_different_time_encodings() {
89	    // Each field is decoded from its own tag: UTCTime in one and
90	    // GeneralizedTime in the other, in both arrangements.
91	    let cert = default_cert(
92	        &utc(b"260115093000Z"),
93	        &generalized(b"20500115093000Z"),
94	    );
95	    let (out, _cert) = run_inspect("mixed-utc-then-gt", &cert);
96	    assert_times_success(&out, "2026-01-15T09:30:00Z", "2050-01-15T09:30:00Z");
97	
98	    let cert = default_cert(
99	        &generalized(b"19990115093000Z"),
100	        &utc(b"490115093000Z"),
101	    );
102	    let (out, _cert) = run_inspect("mixed-gt-then-utc", &cert);
103	    assert_times_success(&out, "1999-01-15T09:30:00Z", "2049-01-15T09:30:00Z");
104	}
105	
106	// ----- Success: timezone independence --------------------------------------
107	
108	#[test]
109	fn output_is_identical_in_every_local_timezone() {
110	    // The values are instants in UTC; the local zone (including date-line
111	    // offsets) must never shift the printed date or time. POSIX TZ strings
112	    // are used so the test needs no zoneinfo files: UTC-14 is fourteen hours
113	    // *ahead* of UTC, HST10 ten hours behind.
114	    let cert = default_cert(
115	        &utc(b"260115093000Z"),
116	        &utc(b"270115093000Z"),
117	    );
118	    let expected = format!(
119	        "Subject: {FIXED_SUBJECT}\n\
120	         Issuer: {FIXED_ISSUER}\n\
121	         Serial Number: {FIXED_SERIAL}\n\
122	         Not Before: 2026-01-15T09:30:00Z\n\
123	         Not After: 2027-01-15T09:30:00Z\n"
124	    );
125	
126	    let zones: &[Option<&str>] = &[
127	        None,
128	        Some(""),
129	        Some("UTC0"),
130	        Some("JST-9"),
131	        Some("IST-5:30"),
132	        Some("UTC-14"),
133	        Some("HST10"),
134	    ];
135	    for (i, zone) in zones.iter().enumerate() {
136	        let label = zone.map_or("unset", |z| if z.is_empty() { "empty" } else { z });
137	        let out = run_inspect_with_tz(&format!("tz-{i}"), &cert, *zone);
138	        assert_eq!(out.status.code(), Some(0), "zone {label}: stderr={}", lossy(&out.stderr));
139	        assert!(out.stderr.is_empty(), "zone {label}: stderr={}", lossy(&out.stderr));
140	        assert_eq!(
141	            lossy(&out.stdout),
142	            expected,
143	            "zone {label} shifted the output"
144	        );
145	    }
146	}
147	
148	// ----- Success: expiry is not a parse error --------------------------------
149	
150	#[test]
151	fn expired_and_not_yet_valid_certificates_still_display() {
152	    // Calendar validity and "is the certificate valid today" are separate
153	    // questions. A long-expired certificate and one far in the future must
154	    // both display regardless of when the test runs (this file pins no
155	    // "today", so the assertion holds on any execution date).
156	    let expired = default_cert(
157	        &utc(b"800101000000Z"), // 1980-01-01T00:00:00Z
158	        &utc(b"990101000000Z"), // 1999-01-01T00:00:00Z
159	    );
160	    let (out, _cert) = run_inspect("expired", &expired);
161	    assert_times_success(&out, "1980-01-01T00:00:00Z", "1999-01-01T00:00:00Z");
162	
163	    let future = default_cert(
164	        &generalized(b"20990101000000Z"),
165	        &generalized(b"21000101000000Z"),
166	    );
167	    let (out, _cert) = run_inspect("not-yet-valid", &future);
168	    assert_times_success(&out, "2099-01-01T00:00:00Z", "2100-01-01T00:00:00Z");
169	}
170	
171	// ----- Success: Gregorian leap years ---------------------------------------
172	
173	#[test]
174	fn february_29_in_2000_and_2004_displays() {
175	    // 2000 is a leap year (divisible by 400). Through UTCTime the digits "00"
176	    // mean 2000 — so this exercises the pivot and the century leap rule at
177	    // once; a "1900" reading would have to reject the date.
178	    let cert = default_cert(
179	        &utc(b"000229000000Z"),
180	        &utc(b"000301000000Z"),
181	    );
182	    let (out, _cert) = run_inspect("leap-2000", &cert);
183	    assert_times_success(&out, "2000-02-29T00:00:00Z", "2000-03-01T00:00:00Z");
184	
185	    // Ordinary divisible-by-four leap year, also via UTCTime.
186	    let cert = default_cert(
187	        &utc(b"040229000000Z"),
188	        &utc(b"040301000000Z"),
189	    );
190	    let (out, _cert) = run_inspect("leap-2004", &cert);
191	    assert_times_success(&out, "2004-02-29T00:00:00Z", "2004-03-01T00:00:00Z");
192	}
193	
194	// ----- Success: boundaries are preserved, not adjusted ---------------------
195	
196	#[test]
197	fn midnight_and_month_end_times_keep_their_values() {
198	    // Exactly-on-boundary values display verbatim: nothing rounds, shifts a
199	    // day, or rejects a midnight / month-end timestamp.
200	    let cert = default_cert(
201	        &utc(b"260101000000Z"),
202	        &utc(b"261231235959Z"),
203	    );
204	    let (out, _cert) = run_inspect("midnight-yearend", &cert);
205	    assert_times_success(&out, "2026-01-01T00:00:00Z", "2026-12-31T23:59:59Z");
206	
207	    // Last instant of the leap day and of a 30-day month.
208	    let cert = default_cert(
209	        &generalized(b"20240229000000Z"),
210	        &generalized(b"20240430235959Z"),
211	    );
212	    let (out, _cert) = run_inspect("leap-monthend", &cert);
213	    assert_times_success(&out, "2024-02-29T00:00:00Z", "2024-04-30T23:59:59Z");
214	}
