310	#[test]
311	fn truncated_time_content_fails_in_either_field() {
312	    // The TLV length announces 30 content bytes but only eight follow; the
313	    // enclosing validity SEQUENCE is itself correctly bounded, so the error
314	    // is the truncated time, in first or second position.
315	    let short = raw_tlv(TAG_UTC_TIME, &[0x1E], b"26011509");
316	
317	    let validity = seq(&concat(&[&short, &good_na()]));
318	    let (out, _cert) = run_inspect("trunc-before", &default_cert_validity(&validity));
319	    assert_invalid_certificate(&out);
320	
321	    let validity = seq(&concat(&[&good_nb(), &short]));
322	    let (out, _cert) = run_inspect("trunc-after", &default_cert_validity(&validity));
323	    assert_invalid_certificate(&out);
324	}
