91	#[test]
92	fn mixed_known_and_unknown_attributes_keep_their_own_forms() {
93	    // Encoded RDN order (display is reversed):
94	    //   SET { C=CN }
95	    //   SET { O=示例公司 }
96	    //   SET { CN=example.com, 1.2.3.4 "abc", 1.2.3.4 "def" }
97	    // The last SET is one multi-valued RDN: joined with '+', never split into
98	    // groups; the repeated unknown attribute appears twice (never merged); the
99	    // adjacent CN stays text; CJK content passes through as raw UTF-8; groups
100	    // are shown in reverse order; '#' is the encoding marker, unescaped.
101	    let subject = name(&[
102	        rdn(&[atv_utf8(C, "CN")]),
103	        rdn(&[atv_utf8(O, "示例公司")]),
104	        rdn(&[
105	            atv_utf8(CN, "example.com"),
106	            atv_utf8(&[1, 2, 3, 4], "abc"),
107	            atv_utf8(&[1, 2, 3, 4], "def"),
108	        ]),
109	    ]);
110	    let issuer = simple_cn_name("Test CA");
111	    let (out, _cert) = run_inspect("mixed", &build_cert(&subject, &issuer));
112	
113	    assert_success(
114	        &out,
115	        "CN=example.com+1.2.3.4=#0C03616263+1.2.3.4=#0C03646566,O=示例公司,C=CN",
116	        "CN=Test CA",
117	    );
118	}
