120	#[test]
121	fn subject_and_issuer_render_independently() {
122	    // Each name reflects only its own attributes: distinct OID sets and value
123	    // encodings must never bleed across Subject/Issuer.
124	    let subject = name(&[
125	        rdn(&[atv_utf8(O, "测试")]),
126	        rdn(&[atv_utf8(CN, "subject.example")]),
127	    ]);
128	    let issuer = name(&[rdn(&[
129	        atv_utf8(CN, "Example CA"),
130	        atv_utf8(&[1, 2, 3, 4], "abc"),
131	    ])]);
132	    let (out, _cert) = run_inspect("separate-names", &build_cert(&subject, &issuer));
133	
134	    assert_success(
135	        &out,
136	        "CN=subject.example,O=测试",
137	        "CN=Example CA+1.2.3.4=#0C03616263",
138	    );
139	}
