141	#[test]
142	fn known_attribute_with_sequence_value_keeps_short_name_and_shows_der_hex() {
143	    // The exact spec example: postalAddress (2.5.4.17) is a known attribute
144	    // whose value is a SEQUENCE { UTF8String "abc" } rather than a string. It
145	    // must render as postalAddress=#30050C03616263 — tag 0x30, length 0x05
146	    // and content verbatim — instead of rejecting the whole certificate.
147	    let value = seq(&tlv(0x0C, b"abc"));
148	    assert_eq!(hex(&value), POSTAL_ADDRESS_ABC_HEX);
149	    let subject = name(&[rdn(&[atv(POSTAL_ADDRESS, &value)])]);
150	    let issuer = simple_cn_name("Test CA");
151	    let (out, _cert) = run_inspect("known-sequence", &build_cert(&subject, &issuer));
152	
153	    assert_success(&out, "postalAddress=#30050C03616263", "CN=Test CA");
154	}
155	
156	#[test]
157	fn known_non_string_value_applies_to_issuer_as_well() {
158	    // The same rule independently governs the Issuer name.
159	    let subject = simple_cn_name("subject.example");
160	    let issuer = name(&[
161	        rdn(&[atv(POSTAL_ADDRESS, &seq(&tlv(0x0C, b"abc")))]),
162	        rdn(&[atv_utf8(CN, "Test CA")]),
163	    ]);
164	    let (out, _cert) = run_inspect("known-sequence-issuer", &build_cert(&subject, &issuer));
165	
166	    assert_success(&out, "CN=subject.example", "CN=Test CA,postalAddress=#30050C03616263");
167	}
