169	#[test]
170	fn known_non_string_value_preserves_long_form_length() {
171	    // A legal long-form length in the value TLV must be carried byte for byte
172	    // after '#', not collapsed and not rebuilt from the parsed content.
173	    let value = tlv(0x04, &vec![0x41u8; 128]); // postalCode as OCTET STRING
174	    let subject = name(&[rdn(&[atv(POSTAL_CODE, &value)])]);
175	    let issuer = simple_cn_name("Test CA");
176	    let (out, _cert) = run_inspect("known-longlen", &build_cert(&subject, &issuer));
177	
178	    let mut expected = String::from("postalCode=#048180");
179	    expected.push_str(&"41".repeat(128));
180	    assert_success(&out, &expected, "CN=Test CA");
181	}
