183	#[test]
184	fn text_hex_and_unknown_values_mix_without_splitting_multivalued_rdn() {
185	    // One multi-valued RDN mixes a text value (CN), a known attribute shown as
186	    // hex (postalAddress SEQUENCE) and an unknown attribute shown as hex
187	    // (1.2.3.4). The group stays joined with '+'; a preceding text RDN and a
188	    // repeated text CN in another RDN keep their order after reversal.
189	    let subject = name(&[
190	        rdn(&[atv_utf8(C, "CN")]),
191	        rdn(&[atv_utf8(CN, "one"), atv_utf8(CN, "two")]),
192	        rdn(&[
193	            atv_utf8(CN, "example.com"),
194	            atv(POSTAL_ADDRESS, &seq(&tlv(0x0C, b"abc"))),
195	            atv_utf8(&[1, 2, 3, 4], "abc"),
196	        ]),
197	    ]);
198	    let issuer = simple_cn_name("Test CA");
199	    let (out, _cert) = run_inspect("known-mixed", &build_cert(&subject, &issuer));
200	
201	    assert_success(
202	        &out,
203	        &format!(
204	            "CN=example.com+postalAddress=#{POSTAL_ADDRESS_ABC_HEX}+1.2.3.4=#0C03616263,\
205	             CN=one+CN=two,C=CN"
206	        ),
207	        "CN=Test CA",
208	    );
209	}
