211	#[test]
212	fn known_attribute_with_bad_string_is_still_rejected_not_hexified() {
213	    // A supported string type that fails to decode must never be salvaged by
214	    // the hex fallback: invalid UTF-8 in a known attribute is still corrupt.
215	    let bad_value = tlv(0x0C, &[0xFF, 0xFE]);
216	    let subject = name(&[rdn(&[atv(POSTAL_ADDRESS, &bad_value)])]);
217	    let issuer = simple_cn_name("Test CA");
218	    let (out, _cert) = run_inspect("known-bad-string", &build_cert(&subject, &issuer));
219	
220	    assert_invalid_certificate(&out);
221	}
