272	// ----- Failure cases -------------------------------------------------------
273	
274	#[test]
275	fn invalid_utf8_in_unknown_attribute_value_is_rejected() {
276	    // Tagged UTF8String but carrying 0xFF 0xFE: an input error even though the
277	    // value would have been shown as hex.
