466	// ----- Certificate / DER construction -------------------------------------
467	//
468	// Only the structural pieces needed here. Lengths are always emitted in the
469	// minimal DER form, except where a test injects raw bytes to exercise
470	// rejection of non-minimal or truncated encodings.
471	
472	fn simple_cn_name(cn: &str) -> Vec<u8> {
473	    name(&[rdn(&[atv_utf8(CN, cn)])])
474	}
475	
476	/// Assemble a complete, parseable v1 DER certificate with fixed serial,
477	/// validity and key material around the supplied Subject/Issuer names.
478	fn build_cert(subject: &[u8], issuer: &[u8]) -> Vec<u8> {
479	    let serial = tlv(0x02, &[0x0E, 0x8A, 0x4C, 0x2F, 0x9B, 0x17, 0xD6, 0x03]);
480	    let validity = seq(&concat(&[
481	        &tlv(0x17, b"260115093000Z"), // UTCTime 2026-01-15T09:30:00Z
482	        &tlv(0x17, b"270115093000Z"), // UTCTime 2027-01-15T09:30:00Z
483	    ]));
484	    let spki = seq(&concat(&[
485	        &seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 1]), &tlv(0x05, &[])])),
486	        &tlv(0x03, &[0x00, 0x01, 0x00]), // BIT STRING, zero unused bits
487	    ]));
488	
489	    let tbs = seq(&concat(&[
490	        &serial,
491	        &signature_algorithm(),
492	        issuer,
493	        &validity,
494	        subject,
495	        &spki,
496	    ]));
497	    seq(&concat(&[&tbs, &signature_algorithm(), &tlv(0x03, &[0x00])]))
498	}
499	
500	fn signature_algorithm() -> Vec<u8> {
501	    // sha256WithRSAEncryption with explicit NULL parameters.
502	    seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 11]), &tlv(0x05, &[])]))
503	}
504	
505	fn name(rdns: &[Vec<u8>]) -> Vec<u8> {
506	    tlv(
507	        0x30,
508	        &concat(&rdns.iter().map(Vec::as_slice).collect::<Vec<_>>()),
509	    )
510	}
511	
512	fn rdn(atvs: &[Vec<u8>]) -> Vec<u8> {
513	    tlv(
514	        0x31,
515	        &concat(&atvs.iter().map(Vec::as_slice).collect::<Vec<_>>()),
516	    )
517	}
518	
519	/// AttributeTypeAndValue ::= SEQUENCE { type OID, value ANY } — `value` is the
520	/// complete DER TLV of the value.
521	fn atv(arcs: &[u64], value: &[u8]) -> Vec<u8> {
522	    seq(&concat(&[&oid(arcs), value]))
523	}
524	
525	fn atv_utf8(arcs: &[u64], text: &str) -> Vec<u8> {
526	    atv(arcs, &tlv(0x0C, text.as_bytes()))
527	}
528	
529	fn oid(arcs: &[u64]) -> Vec<u8> {
530	    assert!(arcs.len() >= 2);
531	    let mut content = oid_arc(arcs[0] * 40 + arcs[1]);
532	    for &arc in &arcs[2..] {
533	        content.extend_from_slice(&oid_arc(arc));
534	    }
535	    tlv(0x06, &content)
536	}
537	
538	fn oid_arc(mut value: u64) -> Vec<u8> {
539	    let mut out = vec![(value % 128) as u8];
540	    value /= 128;
541	    while value > 0 {
542	        out.push(0x80 | (value % 128) as u8);
543	        value /= 128;
544	    }
545	    out.reverse();
546	    out
547	}
548	
549	fn seq(content: &[u8]) -> Vec<u8> {
550	    tlv(0x30, content)
551	}
552	
553	fn tlv(tag: u8, content: &[u8]) -> Vec<u8> {
554	    let mut out = vec![tag];
555	    out.extend_from_slice(&der_len(content.len()));
556	    out.extend_from_slice(content);
557	    out
558	}
559	
560	fn der_len(n: usize) -> Vec<u8> {
561	    if n < 0x80 {
562	        vec![n as u8]
563	    } else {
564	        let mut body = Vec::new();
565	        let mut v = n;
566	        while v > 0 {
567	            body.push((v & 0xFF) as u8);
568	            v >>= 8;
569	        }
570	        body.reverse();
571	        let mut out = vec![0x80 | body.len() as u8];
572	        out.extend_from_slice(&body);
573	        out
574	    }
575	}
576	
577	fn concat(parts: &[&[u8]]) -> Vec<u8> {
578	    let mut out = Vec::new();
579	    for part in parts {
580	        out.extend_from_slice(part);
581	    }
582	    out
583	}
584	
585	fn hex(bytes: &[u8]) -> String {
586	    let mut s = String::with_capacity(bytes.len() * 2);
587	    for b in bytes {
588	        use std::fmt::Write;
589	        write!(s, "{b:02X}").unwrap();
590	    }
591	    s
592	}
593

